/**
 * Copy the approved engineering PDF/DOCX into Vite's public report directory.
 * Both hosting builds depend on these stable names and paths; reject obviously
 * incomplete sources before copying. Reports are not regenerated by this script.
 * Copies preserve bytes and existing download URLs, not document content accuracy.
 */
import { mkdir, copyFile, stat } from "node:fs/promises";
// Vite copies public files unchanged into both dist and dist-pages.
await mkdir("public/reports", { recursive: true });
for (const name of [
  "Cobalt_Engineering_Report.pdf",
  "Cobalt_Engineering_Report.docx",
]) {
  const info = await stat(`docs/${name}`);
  if (info.size < 10000)
    throw new Error(`Missing or incomplete engineering report: ${name}`);
  await copyFile(`docs/${name}`, `public/reports/${name}`);
}
